#[cfg(test)]
mod tests {
    use super::*;
    use gpui_kit::{AppContext as _, Context, Render, TestAppContext, VisualTestContext};
    use std::{cell::Cell, rc::Rc};

    struct PasteProbe {
        input: Entity<InputState>,
        textarea: Entity<TextareaState>,
        multiline: bool,
        disabled: bool,
        read_only: bool,
        hits: Rc<Cell<usize>>,
    }

    impl Render for PasteProbe {
        fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
            let hits = self.hits.clone();
            let handler = move |item: &ClipboardItem, _: &mut Window, _: &mut App| {
                hits.set(hits.get() + 1);
                item.text().as_deref() == Some("asset")
            };
            if self.multiline {
                Textarea::new(&self.textarea)
                    .disabled(self.disabled)
                    .read_only(self.read_only)
                    .on_paste(handler)
                    .into_any_element()
            } else {
                Input::new(&self.input)
                    .disabled(self.disabled)
                    .read_only(self.read_only)
                    .on_paste(handler)
                    .into_any_element()
            }
        }
    }

    #[gpui_kit::test]
    fn paste_hooks_consume_payloads_and_respect_editability(cx: &mut TestAppContext) {
        cx.update(super::super::theme::init);
        for multiline in [false, true] {
            let hits = Rc::new(Cell::new(0));
            let (probe, visual) = cx.add_window_view({
                let hits = hits.clone();
                move |window, cx| PasteProbe {
                    input: cx.new(|cx| InputState::new(window, cx)),
                    textarea: cx.new(|cx| TextareaState::new(window, cx)),
                    multiline,
                    disabled: false,
                    read_only: false,
                    hits,
                }
            });
            let draw = |visual: &mut VisualTestContext| {
                visual.update(|window, cx| window.draw(cx).clear(cx));
            };
            let dispatch = |visual: &mut VisualTestContext, text: &str| {
                visual.update(|window, cx| {
                    if multiline {
                        let textarea = probe.read(cx).textarea.clone();
                        textarea.update(cx, |state, cx| state.focus(window, cx));
                    } else {
                        let input = probe.read(cx).input.clone();
                        input.update(cx, |state, cx| state.focus(window, cx));
                    }
                    cx.write_to_clipboard(ClipboardItem::new_string(text.into()));
                    window.dispatch_action(Box::new(gpui_kit::base::input::Paste), cx);
                });
            };
            let value = |visual: &mut VisualTestContext| {
                visual.update(|_, cx| {
                    let probe = probe.read(cx);
                    if multiline {
                        probe.textarea.read(cx).value().to_string()
                    } else {
                        probe.input.read(cx).value().to_string()
                    }
                })
            };

            draw(visual);
            dispatch(visual, "asset");
            assert_eq!(hits.get(), 1);
            assert_eq!(value(visual), "");

            dispatch(visual, "text");
            assert_eq!(hits.get(), 2);
            assert_eq!(value(visual), "text");

            for (disabled, read_only) in [(true, false), (false, true)] {
                probe.update(visual, |probe, cx| {
                    probe.disabled = disabled;
                    probe.read_only = read_only;
                    cx.notify();
                });
                draw(visual);
                dispatch(visual, "asset");
                assert_eq!(hits.get(), 2);
                assert_eq!(value(visual), "text");
            }
        }
    }
}

//! The shadcn Nova Button visual port.
//!
//! Visual source: shadcn/ui 4.19.0 `button.tsx` and `style-nova.css` at
//! `1773ecfeeb4a04366978d353e69b5c7ded78dcb2`. Interaction comes from the
//! GPUI Kit headless button.

use std::rc::Rc;

use gpui_kit::base::Button as BaseButton;
use gpui_kit::{
    AnyElement, App, ClickEvent, ElementId, FontWeight, IntoElement, ParentElement, RenderOnce,
    SharedString, Styled, Window, px,
};

use super::theme::{ThemeMode, UiRadius, UiTheme};

type ButtonClickHandler = Rc<dyn Fn(&ClickEvent, &mut Window, &mut App) + 'static>;
type ButtonStyleHandler = Rc<dyn Fn(BaseButton) -> BaseButton>;

/// The pinned shadcn Button visual variant.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ButtonVariant {
    /// Primary action.
    #[default]
    Default,
    /// Bordered action.
    Outline,
    /// Secondary action.
    Secondary,
    /// Low-emphasis action.
    Ghost,
    /// Destructive action.
    Destructive,
    /// Link-styled action.
    Link,
}

/// The pinned shadcn Button size.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum ButtonSize {
    /// 24px-high extra-small button.
    Xs,
    /// 28px-high small button.
    Sm,
    /// 32px-high default button.
    #[default]
    Default,
    /// 36px-high large button.
    Lg,
    /// 24px square icon button.
    IconXs,
    /// 28px square icon button.
    IconSm,
    /// 32px square icon button.
    Icon,
    /// 36px square icon button.
    IconLg,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct ButtonMetrics {
    height: f32,
    horizontal_padding: f32,
    gap: f32,
    radius: f32,
    text_size: f32,
    icon_only: bool,
}

impl ButtonSize {
    fn metrics(self, radii: UiRadius) -> ButtonMetrics {
        let radius = f32::from(radii.lg);
        let radius_md = f32::from(radii.md);
        match self {
            Self::Xs => ButtonMetrics::new(24.0, 8.0, 4.0, radius_md.min(10.0), 12.0, false),
            Self::Sm => ButtonMetrics::new(28.0, 10.0, 4.0, radius_md.min(12.0), 12.8, false),
            Self::Default => ButtonMetrics::new(32.0, 10.0, 6.0, radius, 14.0, false),
            Self::Lg => ButtonMetrics::new(36.0, 10.0, 6.0, radius, 14.0, false),
            Self::IconXs => ButtonMetrics::new(24.0, 0.0, 0.0, radius_md.min(10.0), 14.0, true),
            Self::IconSm => ButtonMetrics::new(28.0, 0.0, 0.0, radius_md.min(12.0), 14.0, true),
            Self::Icon => ButtonMetrics::new(32.0, 0.0, 0.0, radius, 14.0, true),
            Self::IconLg => ButtonMetrics::new(36.0, 0.0, 0.0, radius, 14.0, true),
        }
    }
}

impl ButtonMetrics {
    const fn new(
        height: f32,
        horizontal_padding: f32,
        gap: f32,
        radius: f32,
        text_size: f32,
        icon_only: bool,
    ) -> Self {
        Self {
            height,
            horizontal_padding,
            gap,
            radius,
            text_size,
            icon_only,
        }
    }
}

/// A styled Button that keeps GPUI Kit's pointer and keyboard behavior.
#[derive(IntoElement)]
pub struct Button {
    style: gpui_kit::StyleRefinement,
    id: ElementId,
    variant: ButtonVariant,
    size: ButtonSize,
    disabled: bool,
    aria_label: Option<SharedString>,
    on_click: Option<ButtonClickHandler>,
    style_with: Option<ButtonStyleHandler>,
    children: Vec<AnyElement>,
}

impl Button {
    /// Creates a Button with a caller-owned stable ID.
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            style: gpui_kit::StyleRefinement::default(),
            id: id.into(),
            variant: ButtonVariant::default(),
            size: ButtonSize::default(),
            disabled: false,
            aria_label: None,
            on_click: None,
            style_with: None,
            children: Vec::new(),
        }
    }

    /// Sets the visual variant.
    pub fn variant(mut self, variant: ButtonVariant) -> Self {
        self.variant = variant;
        self
    }

    /// Sets the visual size.
    pub fn size(mut self, size: ButtonSize) -> Self {
        self.size = size;
        self
    }

    /// Prevents activation and removes the Button from tab order.
    pub fn disabled(mut self, disabled: bool) -> Self {
        self.disabled = disabled;
        self
    }

    /// Sets the accessible name for icon or custom content. Use `label` for plain text.
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.aria_label = Some(label.into());
        self
    }

    /// Adds visible text and uses it as the accessible name unless one was supplied.
    pub fn label(mut self, label: impl Into<SharedString>) -> Self {
        let label = label.into();
        self.aria_label.get_or_insert_with(|| label.clone());
        self.children.push(label.into_any_element());
        self
    }

    /// Runs for pointer, Enter, or Space activation.
    pub fn on_click(
        mut self,
        handler: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_click = Some(Rc::new(handler));
        self
    }

    /// Replaces the visual styling while retaining button interaction.
    /// Include a visible keyboard focus treatment in custom styles.
    pub fn style_with(mut self, handler: impl Fn(BaseButton) -> BaseButton + 'static) -> Self {
        self.style_with = Some(Rc::new(handler));
        self
    }
}

impl ParentElement for Button {
    fn extend(&mut self, elements: impl IntoIterator<Item = AnyElement>) {
        self.children.extend(elements);
    }
}

impl RenderOnce for Button {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let variant = self.variant;
        let size = self.size;
        let root = BaseButton::new(self.id).disabled(self.disabled);
        let root = match self.style_with {
            Some(style) => style(root),
            None => style_button(root, self.disabled, variant, size, &theme),
        };
        let mut root = super::theme::apply_style(root, &self.style).children(self.children);

        if let Some(label) = self.aria_label {
            root = root.accessibility_label(label);
        }
        if let Some(handler) = self.on_click {
            root = root.on_click(move |event, window, cx| handler(event, window, cx));
        }

        root
    }
}

pub(super) fn style_button<
    T: Styled + gpui_kit::InteractiveElement + gpui_kit::prelude::FluentBuilder,
>(
    base: T,
    disabled: bool,
    variant: ButtonVariant,
    size: ButtonSize,
    theme: &UiTheme,
) -> T {
    let colors = theme.colors;
    let metrics = size.metrics(theme.radius);
    let focus_border = match variant {
        ButtonVariant::Destructive => colors.destructive.opacity(0.40),
        _ => colors.ring,
    };

    let base = base
        .flex()
        .flex_shrink_0()
        .items_center()
        .justify_center()
        .whitespace_nowrap()
        .h(theme.space(metrics.height / 4.))
        .gap(theme.space(metrics.gap / 4.))
        .rounded(px(metrics.radius))
        .border_1()
        .border_color(colors.background.opacity(0.0))
        .font_family(theme.fonts.body.clone())
        .font_weight(FontWeight::MEDIUM)
        .text_size(theme.text(metrics.text_size))
        .focus_visible(move |style| style.border_color(focus_border))
        .when(metrics.icon_only, |base| {
            base.w(theme.space(metrics.height / 4.)).p_0()
        })
        .when(!metrics.icon_only, |base| {
            base.px(theme.space(metrics.horizontal_padding / 4.))
        });

    let base = match variant {
        ButtonVariant::Default => base
            .bg(colors.primary)
            .text_color(colors.primary_foreground)
            .when(!disabled, |base| {
                base.hover(move |style| style.bg(colors.primary.opacity(0.80)))
            }),
        ButtonVariant::Outline => {
            let background = match theme.mode {
                ThemeMode::Light => colors.background,
                ThemeMode::Dark => colors.input.opacity(0.30),
            };
            let border = match theme.mode {
                ThemeMode::Light => colors.border,
                ThemeMode::Dark => colors.input,
            };
            let hover = match theme.mode {
                ThemeMode::Light => colors.muted,
                ThemeMode::Dark => colors.input.opacity(0.50),
            };
            base.bg(background)
                .text_color(colors.foreground)
                .border_color(border)
                .when(!disabled, |base| {
                    base.hover(move |style| style.bg(hover).text_color(colors.foreground))
                })
        }
        ButtonVariant::Secondary => {
            let hover = colors
                .secondary
                .blend(colors.secondary_foreground.opacity(0.08));
            base.bg(colors.secondary)
                .text_color(colors.secondary_foreground)
                .when(!disabled, |base| base.hover(move |style| style.bg(hover)))
        }
        ButtonVariant::Ghost => {
            let hover = match theme.mode {
                ThemeMode::Light => colors.muted,
                ThemeMode::Dark => colors.muted.opacity(0.50),
            };
            base.bg(colors.background.opacity(0.0))
                .text_color(colors.foreground)
                .when(!disabled, |base| {
                    base.hover(move |style| style.bg(hover).text_color(colors.foreground))
                })
        }
        ButtonVariant::Destructive => {
            let background_alpha = match theme.mode {
                ThemeMode::Light => 0.10,
                ThemeMode::Dark => 0.20,
            };
            let hover_alpha = match theme.mode {
                ThemeMode::Light => 0.20,
                ThemeMode::Dark => 0.30,
            };
            base.bg(colors.destructive.opacity(background_alpha))
                .text_color(colors.destructive)
                .when(!disabled, |base| {
                    base.hover(move |style| style.bg(colors.destructive.opacity(hover_alpha)))
                })
        }
        ButtonVariant::Link => base
            .bg(colors.background.opacity(0.0))
            .text_color(colors.primary)
            .when(!disabled, |base| base.hover(|style| style.underline())),
    };

    base.when(!disabled, |base| base.cursor_pointer())
        .when(disabled, |base| base.opacity(0.50).cursor_not_allowed())
}

impl gpui_kit::Styled for Button {
    fn style(&mut self) -> &mut gpui_kit::StyleRefinement {
        &mut self.style
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_variants_expose_clickable_and_disabled_cursors() {
        for theme in [UiTheme::neutral_light(), UiTheme::neutral_dark()] {
            for variant in [
                ButtonVariant::Default,
                ButtonVariant::Outline,
                ButtonVariant::Secondary,
                ButtonVariant::Ghost,
                ButtonVariant::Destructive,
                ButtonVariant::Link,
            ] {
                for disabled in [false, true] {
                    let mut button = style_button(
                        gpui_kit::div(),
                        disabled,
                        variant,
                        ButtonSize::Default,
                        &theme,
                    );
                    assert_eq!(
                        button.style().mouse_cursor,
                        Some(if disabled {
                            gpui_kit::CursorStyle::OperationNotAllowed
                        } else {
                            gpui_kit::CursorStyle::PointingHand
                        })
                    );
                }
            }
        }
    }

    #[test]
    fn nova_sizes_are_exact() {
        let sizes = [
            (ButtonSize::Xs, 24.0, 8.0, 4.0, 8.0),
            (ButtonSize::Sm, 28.0, 10.0, 4.0, 8.0),
            (ButtonSize::Default, 32.0, 10.0, 6.0, 10.0),
            (ButtonSize::Lg, 36.0, 10.0, 6.0, 10.0),
            (ButtonSize::IconXs, 24.0, 0.0, 0.0, 8.0),
            (ButtonSize::IconSm, 28.0, 0.0, 0.0, 8.0),
            (ButtonSize::Icon, 32.0, 0.0, 0.0, 10.0),
            (ButtonSize::IconLg, 36.0, 0.0, 0.0, 10.0),
        ];

        for (size, height, padding, gap, radius) in sizes {
            let metrics = size.metrics(UiRadius::new(px(10.0)));
            assert_eq!(metrics.height, height);
            assert_eq!(metrics.horizontal_padding, padding);
            assert_eq!(metrics.gap, gap);
            assert_eq!(metrics.radius, radius);
        }
    }
}

//! Nova field layout with explicit input state, label focus and validation messages.

use super::{
    input::{Input, InputState, Textarea},
    theme::UiTheme,
};
use gpui_kit::{
    AnyElement, App, Div, ElementId, Entity, FocusHandle, FontWeight, InteractiveElement as _,
    IntoElement, MouseButton, ParentElement as _, RenderOnce, Role, SharedString,
    StatefulInteractiveElement as _, Styled, Window, div, prelude::FluentBuilder as _, px,
};

/// A control that can receive a field's shared name, disabled and invalid state.
pub trait FieldControl: 'static {
    /// Returns the control's real keyboard focus target.
    fn field_focus_handle(&self, cx: &App) -> FocusHandle;
    /// Applies the field state and erases the rendered control type.
    fn into_field_control(self, label: SharedString, disabled: bool, invalid: bool) -> AnyElement;
}

impl FieldControl for Input {
    fn field_focus_handle(&self, cx: &App) -> FocusHandle {
        Input::field_focus_handle(self, cx)
    }

    fn into_field_control(self, label: SharedString, disabled: bool, invalid: bool) -> AnyElement {
        self.aria_label(label)
            .disabled(disabled)
            .invalid(invalid)
            .into_any_element()
    }
}

impl FieldControl for Textarea {
    fn field_focus_handle(&self, cx: &App) -> FocusHandle {
        Textarea::field_focus_handle(self, cx)
    }

    fn into_field_control(self, label: SharedString, disabled: bool, invalid: bool) -> AnyElement {
        self.aria_label(label)
            .disabled(disabled)
            .invalid(invalid)
            .into_any_element()
    }
}

#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
/// The placement of a field label relative to its editor.
pub enum FieldOrientation {
    #[default]
    /// Place the label above the editor.
    Vertical,
    /// Place the label beside the editor.
    Horizontal,
}

#[derive(IntoElement)]
/// A labeled control with application-owned validation feedback.
pub struct Field<C: FieldControl = Input> {
    id: ElementId,
    control: C,
    label: SharedString,
    description: Option<SharedString>,
    error: Option<SharedString>,
    required: bool,
    disabled: bool,
    orientation: FieldOrientation,
    style: gpui_kit::StyleRefinement,
}
impl Field<Input> {
    /// Creates a field around the caller's retained editing state.
    pub fn new(id: impl Into<ElementId>, state: &Entity<InputState>) -> Self {
        Field::from_control(id, Input::new(state))
    }
}
impl<C: FieldControl> Field<C> {
    /// Creates a field around any supported text, choice or number control.
    pub fn from_control(id: impl Into<ElementId>, control: C) -> Self {
        Self {
            id: id.into(),
            control,
            label: SharedString::default(),
            description: None,
            error: None,
            required: false,
            disabled: false,
            orientation: FieldOrientation::Vertical,
            style: Default::default(),
        }
    }
    /// Sets the visible label and the control's accessible name.
    pub fn label(mut self, value: impl Into<SharedString>) -> Self {
        self.label = value.into();
        self
    }
    /// Sets supporting text below the editor.
    pub fn description(mut self, value: impl Into<SharedString>) -> Self {
        self.description = Some(value.into());
        self
    }
    /// Shows validation feedback and marks the editor invalid.
    pub fn error(mut self, value: impl Into<SharedString>) -> Self {
        self.error = Some(value.into());
        self
    }
    /// Marks the field as required in its visible and accessible label.
    pub fn required(mut self, value: bool) -> Self {
        self.required = value;
        self
    }
    /// Disables interaction and applies the disabled appearance.
    pub fn disabled(mut self, value: bool) -> Self {
        self.disabled = value;
        self
    }
    /// Places the label above or beside the editor.
    pub fn orientation(mut self, value: FieldOrientation) -> Self {
        self.orientation = value;
        self
    }
}
impl<C: FieldControl> Styled for Field<C> {
    fn style(&mut self) -> &mut gpui_kit::StyleRefinement {
        &mut self.style
    }
}
impl<C: FieldControl> RenderOnce for Field<C> {
    fn render(self, _: &mut Window, cx: &mut App) -> impl IntoElement {
        let t = UiTheme::read(cx).clone();
        let focus = self.control.field_focus_handle(cx);
        let label = if self.required {
            format!("{} (required)", self.label).into()
        } else {
            self.label.clone()
        };
        let label_view = div()
            .id((self.id.clone(), "label"))
            .flex()
            .items_center()
            .gap(t.space(1.))
            .font_weight(FontWeight::MEDIUM)
            .text_size(t.text(14.))
            .line_height(t.text(20.))
            .child(self.label)
            .when(self.required, |label| label.child(" *"))
            .when(!self.disabled, |label| {
                label
                    .cursor_pointer()
                    .on_mouse_down(MouseButton::Left, move |_, window, cx| {
                        focus.focus(window, cx)
                    })
            });
        let description = self.error.clone().or(self.description.clone());
        let control = self
            .control
            .into_field_control(label, self.disabled, self.error.is_some());
        let root = div()
            .id(self.id)
            .role(Role::Group)
            .w_full()
            .flex()
            .gap(t.space(2.))
            .font_family(t.fonts.body.clone())
            .text_color(t.colors.foreground)
            .when(self.orientation == FieldOrientation::Vertical, |root| {
                root.flex_col()
            })
            .when(self.orientation == FieldOrientation::Horizontal, |root| {
                root.items_center()
            })
            .child(label_view)
            .child(
                div()
                    .flex_1()
                    .min_w_0()
                    .flex()
                    .flex_col()
                    .gap(t.space(1.5))
                    .child(control)
                    .when_some(description, |root, description| {
                        root.child(
                            div()
                                .id("description")
                                .when(self.error.is_some(), |description| {
                                    description.role(Role::Alert)
                                })
                                .text_size(t.text(14.))
                                .line_height(t.text(20.))
                                .text_color(if self.error.is_some() {
                                    t.colors.destructive
                                } else {
                                    t.colors.muted_foreground
                                })
                                .child(description),
                        )
                    }),
            );
        super::theme::apply_style(root, &self.style)
    }
}

/// Stacks related fields with Nova spacing.
pub fn field_group(cx: &App) -> Div {
    div()
        .flex()
        .flex_col()
        .w_full()
        .gap(UiTheme::read(cx).space(7.))
}
/// Stacks a field editor and supporting content.
pub fn field_content(cx: &App) -> Div {
    div()
        .flex()
        .flex_col()
        .flex_1()
        .gap(UiTheme::read(cx).space(1.5))
}
/// Creates a themed field heading.
pub fn field_title(cx: &App) -> Div {
    let t = UiTheme::read(cx);
    div()
        .flex()
        .items_center()
        .gap(t.space(2.))
        .font_family(t.fonts.body.clone())
        .font_weight(FontWeight::MEDIUM)
        .text_size(t.text(14.))
        .line_height(t.text(20.))
        .text_color(t.colors.foreground)
}
/// Creates a horizontal divider between field sections.
pub fn field_separator(cx: &App) -> Div {
    div().w_full().h(px(1.)).bg(UiTheme::read(cx).colors.border)
}

//! Nova input-group composition around the existing Kit-backed text controls.

use super::{
    button::{Button, ButtonSize, ButtonVariant},
    field::FieldControl,
    input::{Input, Textarea},
    theme::{ThemeMode, UiTheme},
};
use gpui_kit::{
    AnyElement, App, ClickEvent, ElementId, FocusHandle, InteractiveElement as _, IntoElement,
    MouseButton, ParentElement, RenderOnce, Role, SharedString, StatefulInteractiveElement as _,
    StyleRefinement, Styled, Window, div, prelude::FluentBuilder as _,
};

/// The logical side of an addon relative to the text control.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum InputGroupAddonAlignment {
    /// Places the addon before a single-line control.
    #[default]
    InlineStart,
    /// Places the addon after a single-line control.
    InlineEnd,
    /// Places the addon above the control.
    BlockStart,
    /// Places the addon below the control.
    BlockEnd,
}

/// A single-line input or multi-line textarea accepted by [`InputGroup`].
pub enum InputGroupControl {
    /// A single-line input.
    Input(Input),
    /// A multi-line textarea.
    Textarea(Textarea),
}

impl From<Input> for InputGroupControl {
    fn from(value: Input) -> Self {
        Self::Input(value)
    }
}

impl From<Textarea> for InputGroupControl {
    fn from(value: Textarea) -> Self {
        Self::Textarea(value)
    }
}

impl InputGroupControl {
    fn focus_handle(&self, cx: &App) -> FocusHandle {
        match self {
            Self::Input(input) => input.field_focus_handle(cx),
            Self::Textarea(textarea) => textarea.field_focus_handle(cx),
        }
    }

    fn is_multiline(&self) -> bool {
        matches!(self, Self::Textarea(_))
    }

    fn is_disabled(&self) -> bool {
        match self {
            Self::Input(input) => input.is_disabled(),
            Self::Textarea(textarea) => textarea.is_disabled(),
        }
    }

    fn is_read_only(&self) -> bool {
        match self {
            Self::Input(input) => input.is_read_only(),
            Self::Textarea(textarea) => textarea.is_read_only(),
        }
    }

    fn is_invalid(&self) -> bool {
        match self {
            Self::Input(input) => input.is_invalid(),
            Self::Textarea(textarea) => textarea.is_invalid(),
        }
    }

    fn render(
        self,
        label: Option<SharedString>,
        disabled: bool,
        read_only: bool,
        invalid: bool,
    ) -> AnyElement {
        match self {
            Self::Input(input) => input
                .when_some(label, |input, label| input.aria_label(label))
                .when(disabled, |input| input.disabled(true))
                .when(read_only, |input| input.read_only(true))
                .when(invalid, |input| input.invalid(true))
                .bordered(false)
                .into_any_element(),
            Self::Textarea(textarea) => textarea
                .when_some(label, |textarea, label| textarea.aria_label(label))
                .when(disabled, |textarea| textarea.disabled(true))
                .when(read_only, |textarea| textarea.read_only(true))
                .when(invalid, |textarea| textarea.invalid(true))
                .bordered(false)
                .into_any_element(),
        }
    }
}

/// A shared Nova frame around one text control and its addons.
#[derive(IntoElement)]
pub struct InputGroup {
    id: ElementId,
    control: InputGroupControl,
    addons: Vec<InputGroupAddon>,
    style: StyleRefinement,
    label: Option<SharedString>,
    disabled: bool,
    read_only: bool,
    invalid: bool,
}

impl InputGroup {
    /// Creates a group around its required text control.
    pub fn new(id: impl Into<ElementId>, control: impl Into<InputGroupControl>) -> Self {
        Self {
            id: id.into(),
            control: control.into(),
            addons: Vec::new(),
            style: Default::default(),
            label: None,
            disabled: false,
            read_only: false,
            invalid: false,
        }
    }

    /// Replaces the group's text control.
    pub fn input(mut self, control: impl Into<InputGroupControl>) -> Self {
        self.control = control.into();
        self
    }

    /// Appends an explicitly aligned addon.
    pub fn addon(mut self, addon: InputGroupAddon) -> Self {
        self.addons.push(addon);
        self
    }

    /// Sets the accessible name of the text control.
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.label = Some(label.into());
        self
    }

    /// Disables the editor and addon actions.
    pub fn disabled(mut self, value: bool) -> Self {
        self.disabled = value;
        self
    }

    /// Prevents edits while preserving selection, copying and addon actions.
    pub fn read_only(mut self, value: bool) -> Self {
        self.read_only = value;
        self
    }

    /// Applies validation error colors and semantics to the editor.
    pub fn invalid(mut self, value: bool) -> Self {
        self.invalid = value;
        self
    }
}

impl Styled for InputGroup {
    fn style(&mut self) -> &mut StyleRefinement {
        &mut self.style
    }
}

impl FieldControl for InputGroup {
    fn field_focus_handle(&self, cx: &App) -> FocusHandle {
        self.control.focus_handle(cx)
    }

    fn into_field_control(self, label: SharedString, disabled: bool, invalid: bool) -> AnyElement {
        self.aria_label(label)
            .disabled(disabled)
            .invalid(invalid)
            .into_any_element()
    }
}

impl RenderOnce for InputGroup {
    fn render(self, window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx).clone();
        let colors = theme.colors;
        let focus = self.control.focus_handle(cx);
        let disabled = self.disabled || self.control.is_disabled();
        let read_only = self.read_only || self.control.is_read_only();
        let invalid = self.invalid || self.control.is_invalid();
        let focused = focus.is_focused(window) && !disabled;
        let multiline = self.control.is_multiline();
        let has_block = self.addons.iter().any(|addon| {
            matches!(
                addon.alignment,
                InputGroupAddonAlignment::BlockStart | InputGroupAddonAlignment::BlockEnd
            )
        });
        let mut inline_start = Vec::new();
        let mut inline_end = Vec::new();
        let mut block_start = Vec::new();
        let mut block_end = Vec::new();
        for addon in self.addons {
            let rendered = addon.render_in_group(disabled, &theme);
            match rendered.0 {
                InputGroupAddonAlignment::InlineStart => inline_start.push(rendered.1),
                InputGroupAddonAlignment::InlineEnd => inline_end.push(rendered.1),
                InputGroupAddonAlignment::BlockStart => block_start.push(rendered.1),
                InputGroupAddonAlignment::BlockEnd => block_end.push(rendered.1),
            }
        }
        let control = self
            .control
            .render(self.label.clone(), disabled, read_only, invalid);
        let background = match theme.mode {
            ThemeMode::Light => colors.background.opacity(0.),
            ThemeMode::Dark => colors.input.opacity(0.3),
        };
        let border = if invalid {
            colors.destructive
        } else if focused {
            colors.ring
        } else {
            colors.input
        };
        let click_focus = focus.clone();
        let root = div()
            .id(self.id)
            .role(Role::Group)
            .w_full()
            .min_w_0()
            .flex()
            .flex_col()
            .rounded(theme.radius.lg)
            .border_1()
            .border_color(border)
            .bg(background)
            .font_family(theme.fonts.body.clone())
            .text_color(colors.foreground)
            .when(!multiline && !has_block, |root| root.h(theme.space(8.)))
            .when(disabled, |root| {
                root.opacity(0.5)
                    .cursor_not_allowed()
                    .capture_any_mouse_down(|_, _, cx| cx.stop_propagation())
                    .capture_key_down(|event, _, cx| {
                        if event.keystroke.key != "tab" {
                            cx.stop_propagation();
                        }
                    })
            })
            .when(!disabled, |root| {
                root.on_mouse_down(MouseButton::Left, move |_, window, cx| {
                    if !window.default_prevented() {
                        click_focus.focus(window, cx);
                        window.prevent_default();
                    }
                })
            })
            .children(block_start)
            .child(
                div()
                    .flex()
                    .w_full()
                    .min_w_0()
                    .items_center()
                    .when(!multiline && !has_block, |row| row.h_full())
                    .children(inline_start)
                    .child(div().flex_1().min_w_0().child(control))
                    .children(inline_end),
            )
            .children(block_end);
        super::theme::apply_style(root, &self.style)
    }
}

enum InputGroupAddonChild {
    Element(AnyElement),
    Button(Box<InputGroupButton>),
}

/// Text, icons, buttons or custom content on one side of an input group.
#[derive(IntoElement)]
pub struct InputGroupAddon {
    id: ElementId,
    alignment: InputGroupAddonAlignment,
    children: Vec<InputGroupAddonChild>,
    style: StyleRefinement,
}

impl InputGroupAddon {
    /// Creates an inline-start addon with a stable ID.
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            id: id.into(),
            alignment: Default::default(),
            children: Vec::new(),
            style: Default::default(),
        }
    }

    /// Sets the addon's position around the text control.
    pub fn align(mut self, alignment: InputGroupAddonAlignment) -> Self {
        self.alignment = alignment;
        self
    }

    /// Adds a compact action that inherits the group's disabled state.
    pub fn button(mut self, button: InputGroupButton) -> Self {
        self.children
            .push(InputGroupAddonChild::Button(Box::new(button)));
        self
    }

    fn render_in_group(
        self,
        disabled: bool,
        theme: &UiTheme,
    ) -> (InputGroupAddonAlignment, AnyElement) {
        let alignment = self.alignment;
        let children = self.children.into_iter().map(|child| match child {
            InputGroupAddonChild::Element(child) => child,
            InputGroupAddonChild::Button(button) => (*button).disabled(disabled).into_any_element(),
        });
        let root = div()
            .id(self.id)
            .flex()
            .flex_none()
            .items_center()
            .gap(theme.space(2.))
            .font_family(theme.fonts.body.clone())
            .text_size(theme.text(14.))
            .text_color(theme.colors.muted_foreground)
            .cursor_text()
            .when(
                matches!(alignment, InputGroupAddonAlignment::InlineStart),
                |root| root.pl(theme.space(1.5)),
            )
            .when(
                matches!(alignment, InputGroupAddonAlignment::InlineEnd),
                |root| root.pr(theme.space(1.5)),
            )
            .when(
                matches!(alignment, InputGroupAddonAlignment::BlockStart),
                |root| {
                    root.w_full()
                        .justify_start()
                        .px(theme.space(2.5))
                        .pt(theme.space(2.))
                },
            )
            .when(
                matches!(alignment, InputGroupAddonAlignment::BlockEnd),
                |root| {
                    root.w_full()
                        .justify_start()
                        .px(theme.space(2.5))
                        .pb(theme.space(2.))
                },
            )
            .children(children);
        (
            alignment,
            super::theme::apply_style(root, &self.style).into_any_element(),
        )
    }
}

impl ParentElement for InputGroupAddon {
    fn extend(&mut self, elements: impl IntoIterator<Item = AnyElement>) {
        self.children
            .extend(elements.into_iter().map(InputGroupAddonChild::Element));
    }
}

impl Styled for InputGroupAddon {
    fn style(&mut self) -> &mut StyleRefinement {
        &mut self.style
    }
}

impl RenderOnce for InputGroupAddon {
    fn render(self, _: &mut Window, cx: &mut App) -> impl IntoElement {
        self.render_in_group(false, UiTheme::read(cx)).1
    }
}

/// The single-line control used by an input group.
pub type InputGroupInput = Input;

/// The multi-line control used by an input group.
pub type InputGroupTextarea = Textarea;

/// A compact input-group action backed by gpuicn's Button.
#[derive(IntoElement)]
pub struct InputGroupButton {
    button: Button,
    disabled: bool,
}

impl InputGroupButton {
    /// Creates a compact ghost button with a stable ID.
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            button: Button::new(id)
                .variant(ButtonVariant::Ghost)
                .size(ButtonSize::Xs),
            disabled: false,
        }
    }

    /// Sets the visible button label.
    pub fn label(mut self, label: impl Into<SharedString>) -> Self {
        self.button = self.button.label(label);
        self
    }

    /// Sets the name announced to accessibility clients.
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.button = self.button.aria_label(label);
        self
    }

    /// Disables the action. A group-level disabled state is combined with this value.
    pub fn disabled(mut self, value: bool) -> Self {
        self.disabled |= value;
        self
    }

    /// Runs a callback when the enabled button is activated.
    pub fn on_click(
        mut self,
        handler: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.button = self.button.on_click(handler);
        self
    }
}

impl ParentElement for InputGroupButton {
    fn extend(&mut self, elements: impl IntoIterator<Item = AnyElement>) {
        self.button.extend(elements);
    }
}

impl Styled for InputGroupButton {
    fn style(&mut self) -> &mut StyleRefinement {
        self.button.style()
    }
}

impl RenderOnce for InputGroupButton {
    fn render(self, _: &mut Window, _: &mut App) -> impl IntoElement {
        self.button.disabled(self.disabled)
    }
}

/// Muted helper text inside an input group.
#[derive(IntoElement, Default)]
pub struct InputGroupText {
    style: StyleRefinement,
    children: Vec<AnyElement>,
}

impl InputGroupText {
    /// Creates an empty muted text container.
    pub fn new() -> Self {
        Self::default()
    }
}

impl ParentElement for InputGroupText {
    fn extend(&mut self, elements: impl IntoIterator<Item = AnyElement>) {
        self.children.extend(elements);
    }
}

impl Styled for InputGroupText {
    fn style(&mut self) -> &mut StyleRefinement {
        &mut self.style
    }
}

impl RenderOnce for InputGroupText {
    fn render(self, _: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = UiTheme::read(cx);
        let root = div()
            .flex()
            .items_center()
            .gap(theme.space(2.))
            .text_size(theme.text(14.))
            .text_color(theme.colors.muted_foreground)
            .children(self.children);
        super::theme::apply_style(root, &self.style)
    }
}
